window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-9801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1283 na letra δ · nº geral 9801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 evaporar; exalar suor; transpirar; suar 2 eva­porar-se. 〈διά, ἀτμίζω〉</p></section></article>\n<article id=\"entry-dgp-9802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1284 na letra δ · nº geral 9802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de cortar em dois; equação; divisão 2 fio (dos dentes) 3 buraco; perfuração. 〈διατέμνω〉</p></section></article>\n<article id=\"entry-dgp-9803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατοξεύσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1285 na letra δ · nº geral 9803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o que se pode atingir a tiro de arco. 〈διατοξεύω〉</p></section></article>\n<article id=\"entry-dgp-9804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατοξεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1286 na letra δ · nº geral 9804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançar como uma flecha ♦ méd. 2 lutar com arco 3 disputar o prêmio do arco.</p></section></article>\n<article id=\"entry-dgp-9805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1287 na letra δ · nº geral 9805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gravar; cinzelar.</p></section></article>\n<article id=\"entry-dgp-9806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατορνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1288 na letra δ · nº geral 9806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fabricar em volta; tornear.</p></section></article>\n<article id=\"entry-dgp-9807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάτορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1289 na letra δ · nº geral 9807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que transpassa; que penetra na carne 2 penetrante (som, pavor). 〈διά, τείρω〉</p></section></article>\n<article id=\"entry-dgp-9808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατραγῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1290 na letra δ · nº geral 9808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">declamar com ênfase trágica.</p></section></article>\n<article id=\"entry-dgp-9809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατραχηλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1291 na letra δ · nº geral 9809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colocar o pescoço sob o jugo 2 precipitar-se de cabeça.</p></section></article>\n<article id=\"entry-dgp-9810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατραχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1292 na letra δ · nº geral 9810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar muito rude ♦ méd. 2 tornar-se muito rude.</p></section></article>\n<article id=\"entry-dgp-9811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρεπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1293 na letra δ · nº geral 9811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para dissuadir; próprio para desviar. 〈διατρέπω〉</p></section></article>\n<article id=\"entry-dgp-9812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1294 na letra δ · nº geral 9812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατρέψω; pas. aor.2 διετράπην) 1 desviar; dissuadir alguém, ac., de, gen. ou τοῦ μή ou πρὸς τὸ μή e inf.: δ. πρὸς τὸ μὴ ἀπολιπεῖν arr. impedir de abandonar ♦ pas. 2 desviar-se por confusão, por vergonha 3 perturbar-se.</p></section></article>\n<article id=\"entry-dgp-9813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1295 na letra δ · nº geral 9813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nutrir; manter; sustentar.</p></section></article>\n<article id=\"entry-dgp-9814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1296 na letra δ · nº geral 9814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαδραμοῦμαι, aor.2 διέδραρμον etc.) 1 correr através; percorrer, ac.: δ. ἁλμυρὸν ὕδωρ hom. a água salgada 2 percorrer do começo ao fim: δ. τὸν βίον plat. atravessar a vida; percorrer a vida, δ. τὰ ἡδέα xen. gozar todos os prazeres, δ. τὸν λόγον plat. chegar ao fim de seu discurso 3 penetrar até, εἰς e ac. ou μέχρι e gen. 4 espalhar-se por, gen.: θροῦς διέδραμε τῆς ἐκκλησίας plut. um burburinho percorreu a assembléia toda 5 (o tempo) correr daqui para lá; esvair-se; escoar-se.</p></section></article>\n<article id=\"entry-dgp-9815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1297 na letra δ · nº geral 9815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διέτρεσα) fugir apavorado.</p></section></article>\n<article id=\"entry-dgp-9816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατριβή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1298 na letra δ · nº geral 9816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 modo de ocupar-se; modo de vida; ocupação 2 ocupação séria; estudo; trabalho 3 passa-tempo; divertimento; distração 4 perda de tempo; atraso; demora 5 conversa; colóquio 6 tratado de filosofia 7 escola filosófica 8 lugar de aprendizagem; escola 9 balneário. 〈διατρίβω〉</p></section></article>\n<article id=\"entry-dgp-9817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 1299 na letra δ · nº geral 9817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατρίψω; pas. aor.2 διετρίβην, perf. διατέτριμμαι) 1 esfregar fortemente; amassar; triturar; raspar 2 gastar; consumir: χρήματα δ. teóg. dissipar riquezas 3 despender (tempo), ac.: δ. θερείην her. passar o verão, δ. χρόνον lís. passar o tempo 4 empregar o tempo; passar a vida em algo, ἐν ou ἐπί ou πρός e dat., ἀμφί ou περί e ac., ou com part.: δ. ἐν φιλοσοφίᾳ plat. dedicar-se à filosofia, διατρίβουσι μελετῶσαι τὰ ἄλλα xen. passam o tempo ocupadas com outras atividades, δ. μετ᾽ ἀλλήλων plat. passar o tempo conversando uns com os outros 5 perder tempo; demorar-se; atrasar-se em algo, gen. ou part.: δ. ὁδοῖο hom. retardar-se no caminho, καθ᾽ ἕκαστα λέγων δ. isócr. perder tempo tratando de cada coisa em particular, ἀλλὰ λέγε καὶ μὴ διάτριβε plat. vamos! fala sem demora! 6 protelar; frustrar; atrapalhar: δ. γάμον hom. retardar o casamento ♦ méd. 7 adiar; diferir.</p></section></article>\n<article id=\"entry-dgp-9818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατριπτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1300 na letra δ · nº geral 9818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διατρίβω.</p></section></article>\n<article id=\"entry-dgp-9819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάτριχα</h1><div class=\"entry-meta\"><span>DGP · ordem 1301 na letra δ · nº geral 9819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διὰ τρίχα adv. em três; em três partes.</p></section></article>\n<article id=\"entry-dgp-9820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάτροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1302 na letra δ · nº geral 9820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">variado; cambiante. 〈διατρέπω〉</p></section></article>\n<article id=\"entry-dgp-9821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατροφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1303 na letra δ · nº geral 9821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alimento; sustento. 〈διατρέφω〉</p></section></article>\n<article id=\"entry-dgp-9822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρύγιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1304 na letra δ · nº geral 9822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que fornece sucessivas colheitas. 〈διά, τρύγη〉</p></section></article>\n<article id=\"entry-dgp-9823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρυπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1305 na letra δ · nº geral 9823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">furar; penetrar; cavar.</p></section></article>\n<article id=\"entry-dgp-9824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρυφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1306 na letra δ · nº geral 9824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viver na moleza.</p></section></article>\n<article id=\"entry-dgp-9825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρυφέν</h1><div class=\"entry-meta\"><span>DGP · ordem 1307 na letra δ · nº geral 9825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. n. de διαθρύπτω.</p></section></article>\n<article id=\"entry-dgp-9826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατρώγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1308 na letra δ · nº geral 9826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διατρώξομαι, aor.2 διέτραγον) 1 devorar; roer, ac. 2 comer, gen.</p></section></article>\n<article id=\"entry-dgp-9827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαττάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1309 na letra δ · nº geral 9827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer passar no crivo. 〈δίαττος〉</p></section></article>\n<article id=\"entry-dgp-9828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάττησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1310 na letra δ · nº geral 9828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de passar no crivo. 〈διαττάω〉</p></section></article>\n<article id=\"entry-dgp-9829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαττος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1311 na letra δ · nº geral 9829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crivo.</p></section></article>\n<article id=\"entry-dgp-9830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διᾴττω</h1><div class=\"entry-meta\"><span>DGP · ordem 1312 na letra δ · nº geral 9830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διάττω = διαΐσσω.</p></section></article>\n<article id=\"entry-dgp-9831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατυπόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1313 na letra δ · nº geral 9831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 formar; modelar: δ. νόμους luc. redigir leis 2 imaginar; conceber ♦ méd. 3 imaginar.</p></section></article>\n<article id=\"entry-dgp-9832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διατύπωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1314 na letra δ · nº geral 9832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forma plena e inteira; forma acabada 2 configuração; representação; desenho 3 descrição oratória. 〈διατυπόω〉</p></section></article>\n<article id=\"entry-dgp-9833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαυγάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1315 na letra δ · nº geral 9833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brilhar; lançar seu brilho; lançar sua luz 2 começar a brilhar, a despontar. 〈διά, αὐγάζω〉</p></section></article>\n<article id=\"entry-dgp-9834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαυγασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1316 na letra δ · nº geral 9834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">clarão brilhante; esplendor. 〈δια­υ­γάζω〉</p></section></article>\n<article id=\"entry-dgp-9835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαύγεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1317 na letra δ · nº geral 9835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esplendor; claridade transparente; trans­parência 2 clareza do discurso 3 abertura por onde penetra a luz. 〈διαυγής〉</p></section></article>\n<article id=\"entry-dgp-9836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαυγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1318 na letra δ · nº geral 9836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brilhar; despontar; manifestar-se 2 começar a brilhar, a despontar. 〈διαυγής〉</p></section></article>\n<article id=\"entry-dgp-9837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαυγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1319 na letra δ · nº geral 9837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esplendoroso; brilhante 2 transparente; límpido. 〈διά, αὐγή〉</p></section></article>\n<article id=\"entry-dgp-9838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαυλος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1320 na letra δ · nº geral 9838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corrida dupla, percurso de ida e volta no estádio 2 trajeto de ir e vir: δίαυλοι κυμάτων eur. fluxo e refluxo. 〈δίς, αὐλός〉</p></section></article>\n<article id=\"entry-dgp-9839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαυλος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1321 na letra δ · nº geral 9839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passagem estreita; desfiladeiro 2 pl. narinas. 〈διά, αὐλός〉</p></section></article>\n<article id=\"entry-dgp-9840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφαγεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1322 na letra δ · nº geral 9840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de διεσθίω.</p></section></article>\n<article id=\"entry-dgp-9841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1323 na letra δ · nº geral 9841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deixar ver; deixar entrever; mostrar 2 fazer-se ver; mostrar-se: ἠὼς διέφαινε her. a aurora mostrava-se, ἡμέρης διαφαινούσης pol. ao romper do dia, διέφαινε πυρά pínd. as chamas abriam-se ♦ méd. 3 deixar-se ver; deixar-se entrever; revelar-se; aparecer 4 brilhar; resplandecer 5 mostrar-se claramente; ser evidente.</p></section></article>\n<article id=\"entry-dgp-9842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1324 na letra δ · nº geral 9842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que deixa ver; límpido; diáfano 2 que se deixa ver; que se vê nitidamente; distinto 3 brilhante; resplandecente 4 ilustre; famoso 5 claro; evidente (palavra). 〈διαφαίνω〉</p></section></article>\n<article id=\"entry-dgp-9843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφανῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1325 na letra δ · nº geral 9843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. claramente; evidentemente.</p></section></article>\n<article id=\"entry-dgp-9844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφαρμακεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1326 na letra δ · nº geral 9844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tratar com remédios; cuidar.</p></section></article>\n<article id=\"entry-dgp-9845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1327 na letra δ · nº geral 9845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transparência; limpidez. 〈διαφαίνω〉</p></section></article>\n<article id=\"entry-dgp-9846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφαυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1328 na letra δ · nº geral 9846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">resplandecência luminosa; luz; resplendor. 〈διαφαύσκω〉</p></section></article>\n<article id=\"entry-dgp-9847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφαύσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1329 na letra δ · nº geral 9847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) começar a brilhar; aparecer; despontar. 〈διά, φάος〉</p></section></article>\n<article id=\"entry-dgp-9848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφειμένος</h1><div class=\"entry-meta\"><span>DGP · ordem 1330 na letra δ · nº geral 9848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. pas. de διαφίημι.</p></section></article>\n<article id=\"entry-dgp-9849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφερόντως</h1><div class=\"entry-meta\"><span>DGP · ordem 1331 na letra δ · nº geral 9849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de maneira diferente; diferentemente; de outra maneira que, com gen. ou ἤ 2 em grau diferente 3 de modo especial. 〈διαφέρω〉</p></section></article>\n<article id=\"entry-dgp-9850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1332 na letra δ · nº geral 9850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διοίσω, aor.1 διήνεγκα etc.; méd. fut. διοίσομαι, aor. διηνέχθην; pas. aor. διηνέχθην etc.) ativa 1 levar através de; transportar algo, ac., através de, ac., para, εἰς e ac. 2 portar ou conduzir até o fim; suportar; sustentar, ac. 3 levar de um lado a outro; espalhar; difundir; distribuir 4 levar a direções contrárias; fazer girar em todas as direções; sacudir 5 importunar; transtornar; fatigar 6 emitir (o voto) 7 passar (a vida, o tempo), ac.; passar a vida; viver 8 ir além de; superar; vencer alguém, ac. ou gen., em algo, ac. ou dat. ou περί, πρός, κατά ou εἰς e ac., ou ἐν ou ἐπί e dat. 9 ir em direção contrária; ser diferente de; distinguir-se de, gen., em algo, ac., ἐν e dat. 10 impes. faz diferença; é importante; importa a alguém, dat.; suj. or. inf. ou cond. (εἰ) média 11 divergir de; discordar de alguém, dat. ou πρός e ac., em algo, dat. 12 disputar; lutar por algo, περί ou ἀμφί e gen., ἐν e dat. 13 passar o tempo; viver; durar; manter-se 1 ἔδοξε διαφέρειν τὸν ἰσθμὸν τὰς ἡμισέας τῶν νεῶν tuc. decidiu-se transportar a metade das naus para além do istmo, δ. τὸ ἤλεκτρον εἰς τοὺς Ἕλληνας artt. levar o âmbar para os helenos 2 δ. σκῆπτρα eur. deter o cetro, γαστρὸς διήνεγκ᾽ ὄγκον eur. levou até o fim o fardo do ventre, i.e., a gravidez, ῥᾷστα γὰρ τὸ σόν τε σὺ κἀγὼ διοίσω τοὐμόν sóf. pois suportarás facilmente tua sorte e eu, a minha, τὸν πρὸς Πελοποννησίους πόλεμον προθύμως διαφέρειν tuc. sustentar com ardor a guerra contra os peloponésios 3 διαφέρειν τὰς ἀγγελίας τὰς παρὰ ∆ιός luc. levar de um lado para outro as mensagens de Zeus, δ. εἰς ἅπαντας τὴν ἐκείνου μνήμην dem. difundir para todos a memória dele, τοὺς ἐράνους διενεγκεῖν licurgo distribuir as cotas 4 ὅπλισμα διαφέρων eur. brandindo a arma, γλῶσσαν διοίσει sóf. vai pôr a língua em movimento, i.e., vai falar 5 δεῖ τὰς ψυχὰς διαφέρειν μετὰ δεῖπνον μήτε πράγμασι μήτε φροντίσι plut. não é preciso fatigar a alma após a refeição nem com afazeres nem com preocupações, διαλγὴς ἄτα διαφέρει τὸν αἴτιον ésql. a maldição dolorosa transtorna o culpado 6 δ. τὴν ψήφον her. emitir o voto, ἀναγκάσαντες τὸν δῆμον ψῆφον φανερὰν διενηγκεῖν tuc. tendo forçado o povo a emitir o voto aberto 7 δ. νύκτα eur. passar a noite, δ. τὸν αἰῶνα her. passar a vida, θεοὺς σέβων βίον διήνεγκε eur. passou a vida honrando os deuses, ἄπαις διοίσει eur. passará a vida sem filhos 8 διήνεγκε τῶν ἄλλων βασιλέων xen. foi superior aos outros reis, δ. ἀρετῇ τοὺς ἄλλους d.s. vencer os outros em virtude,τάχει καὶ ῥώμῃ καὶ τόλμῃ διέφερον isócr destacavam-se pela rapidez, pela força e pela ousadia, ἀνὴρ πρὸς δικαιοσύνην διαφέρων ésql. homem superior pela justiça 9 ἐσκόπει τί διαφέρει μανίας ἀμαθία xen. examinava em quê a ignorância difere da loucura, διαφέρει ἐν παντὶ ἔργῳ προθυμία ἀθυμίας xen. o ardor difere em tudo da falta de coragem, οὐδὲν διαφέρει ἢ μὴ κεῖσθαι νόμον ἢ μὴ νόμῳ χρῆσθαι artt. em nada são diferentes a ausência da lei e a inexecução da lei 10 πολὺ διαφέρει ὡς βέλτιστα τὸ σῶμα ἔχειν xen. importa muito ter o corpo no melhor estado possível, δοκῶ τοῖς θανοῦσι διαφέρειν βραχὺ εἰ πλουσίων τις τεύξεται κτερισμάτων eur. penso que pouco importa aos mortos se alguém alcançará ricas exéquias, τί δ᾽ ὑμῖν διαφέρει; dem. o que importa a vocês?, τὸ κοινῷ διαφέρον her. o interesse comum, τὰ διαφέροντα πράγματα plut. os afazeres importantes, ὑπὲρ πραγμάτων μεγάλων καί σοι διαφερόντων plut. acerca de assuntos graves e importantes para ti 11 δ. πρὸς ἀλλήλοις ταῖς γνώμαις pol. divergir de opinião uns com os outros, διαφερόμενοι ἐτύγχανον τοῖς Λακεδαιμονίοις tuc. calhava que divergiam dos lacedemônios, οὐχ ὁμολογῶ σοὶ ἀλλὰ πάνυ διαφέρομαι plat. não estou de acordo contigo, pelo contrário, discordo muito 12 μηδὲν διαφέρου περὶ τούτου ar. não brigues por isso 13 ὑγιηροὶ διαφέρονται hipócr. vivem com saúde, σοῦ διοίσεται μόνος sóf. viverá sem ti.</p></section></article>\n<article id=\"entry-dgp-9851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφεύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1333 na letra δ · nº geral 9851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφεύξομαι, aor.2 διέφυγον etc.) 1 (pessoa) fugir; evitar; escapar de, ac.: ὅρα μὴ διαφύγῃ luc. cuida para que ele não fuja, δ. θάνατον plat. escapar da morte, διαφεύγειν τὸ ἀποδείκνυσθαι γνώμην xen. evitar mostrar sua opinião 2 (coisa) escapar da memória de alguém, ac.; sair do espírito; sair da memória: τοῦτο διαφεύγει με plat. isso me escapa, i.e., ignoro isso, πολλά με διαπέφευγεν isócr. esqueci muitas coisas ♦ pas. 3 tard. ser evitado: διαφεύχθη ὁ κίνδυνος jos. evitou-se o perigo.</p></section></article>\n<article id=\"entry-dgp-9852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφευκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1334 na letra δ · nº geral 9852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levado a fugir. 〈διαφεύγω〉</p></section></article>\n<article id=\"entry-dgp-9853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφευξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1335 na letra δ · nº geral 9853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio de fuga; meio de escapar. 〈διαφεύγω〉</p></section></article>\n<article id=\"entry-dgp-9854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφῆκα, διαφήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1336 na letra δ · nº geral 9854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαφίημι.</p></section></article>\n<article id=\"entry-dgp-9855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφημίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1337 na letra δ · nº geral 9855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διεφήμιζον, aor. διεφήμισα) at. e méd. tornar conhecido; divulgar, disseminar. 〈διά, φήμη〉</p></section></article>\n<article id=\"entry-dgp-9856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1338 na letra δ · nº geral 9856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">anteceder; chegar primeiro.</p></section></article>\n<article id=\"entry-dgp-9857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθαρέεται</h1><div class=\"entry-meta\"><span>DGP · ordem 1339 na letra δ · nº geral 9857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. fut. pas. jôn. de διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-9858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθαρήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1340 na letra δ · nº geral 9858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. pas. de διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-9859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθείρεσκε</h1><div class=\"entry-meta\"><span>DGP · ordem 1341 na letra δ · nº geral 9859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. at. iter. de διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-9860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1342 na letra δ · nº geral 9860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφθερῶ, aor. διέφθειρα, perf.1 διέφθαρκα, perf.2 διέφθορα; pas. aor.2 διεφθάρην, perf. διέφθαρμαι) 1 destruir; perder; fazer perecer; fazer desaparecer: ἡδ᾽ ἡμέρα φύσει σε καὶ διαφθερεῖ sóf. este dia te fará nascer e perecer 2 estragar; gastar: σῦς διέφθειρε τὰ ἔργα her. um javali devastou as culturas 3 perder; corromper; alterar; abalar: τοὺς μὴ διαφθειρομένους ὑπὸ τῶν εὐπραγιῶν isócr. os que não se deixam corromper pelo sucesso, τὰς φρένας διέφθορε θνητῶν eur. alterou a mente dos mortais 4 bíbl. adotar uma conduta corrupta; pecar: πάλιν διέφθειραν sept. reincidiram em pecado 5 estar perdido ♦ at. e méd. 6 abortar ♦ pas. 7 perder-se; ser destruído; cair em ruínas 8 perf. estar arruínado; estar corrompido 9 estar perdido; estar aniquilado, com ac. de rel.: τὰ σκέλεα διεφθάρησαν her. tiveram suas pernas destruídas, τὰ ὄμματα διεφθαρμένος plat. que tem os olhos destruídos; que perdeu a visão.</p></section></article>\n<article id=\"entry-dgp-9861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθέρσει</h1><div class=\"entry-meta\"><span>DGP · ordem 1343 na letra δ · nº geral 9861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. fut. at. ép. de διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-9862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1344 na letra δ · nº geral 9862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perda; destruição; ruína 2 corrupção; sedução 3 objeto de destruição; presa; joguete 4 Medic. aborto. 〈διαφθείρω〉</p></section></article>\n<article id=\"entry-dgp-9863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφθορεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1345 na letra δ · nº geral 9863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">corruptor; profanador; agente de corrupção. 〈διαφθείρω〉</p></section></article>\n<article id=\"entry-dgp-9864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1346 na letra δ · nº geral 9864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφήσω, aor. διαφῆκα etc.) deixar ir; despedir; dar baixa em, ac.</p></section></article>\n<article id=\"entry-dgp-9865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφιλονεικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1347 na letra δ · nº geral 9865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διεφιλονείκησα) estar em luta; discutir duramente.</p></section></article>\n<article id=\"entry-dgp-9866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφιλοτιμέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1348 na letra δ · nº geral 9866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφιλοτιμήσομαι) 1 aplicar-se com zelo; aplicar-se com emulação 2 rivalizar com alguém, dat., por algo, ὑπέρ e gen.</p></section></article>\n<article id=\"entry-dgp-9867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφλέγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1349 na letra δ · nº geral 9867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abrasar; inflamar ♦ pas. 2 inflamar-se.</p></section></article>\n<article id=\"entry-dgp-9868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφοιβάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1350 na letra δ · nº geral 9868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. pas. inf. διαπεφοίβασθαι) agitar por um transporte furioso; pôr fora de si, alguém, ac.</p></section></article>\n<article id=\"entry-dgp-9869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφοιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1351 na letra δ · nº geral 9869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφοιτήσω) 1 percorrer em todos os sentidos, ac. 2 estender-se de um lado a outro; propalar-se; difundir-se, gen. ou διά e ac.</p></section></article>\n<article id=\"entry-dgp-9870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφοιτέοντας</h1><div class=\"entry-meta\"><span>DGP · ordem 1352 na letra δ · nº geral 9870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. pl. jôn. de διαφοιτάω.</p></section></article>\n<article id=\"entry-dgp-9871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1353 na letra δ · nº geral 9871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 diferença; diversidade 2 variedade; espécie 3 distinção; excelência 4 rar. vantagem; proveito 5 desacordo; contestação; divergência 6 movimento; extravio (do espírito). 〈διαφέρω〉</p></section></article>\n<article id=\"entry-dgp-9872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1354 na letra δ · nº geral 9872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφορήσω) 1 levar de um lado e de outro; dispersar; dissipar; difundir 2 levar embora; pilhar; devastar 3 partir em pedaços; despedaçar; abater 4 dissolver 5 relaxar; amolecer; debilitar 6 Medic. eliminar (humores); fazer evaporar 7 intr. ser levado de um lado a outro; ficar indeciso.</p></section></article>\n<article id=\"entry-dgp-9873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφόρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1355 na letra δ · nº geral 9873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pilhagem; roubo 2 ação de ser levado de um lado a outro; indecisão; perplexidade 3 Medic. evaporação; eliminação de humores. 〈διαφορέω〉</p></section></article>\n<article id=\"entry-dgp-9874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1356 na letra δ · nº geral 9874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 diverso; diferente de, gen. ou dat. 2 que se diferencia; variado 3 distinto; notável; superior 4 vantajoso; proveitoso; útil; importante, πρός e ac. 5 em desacordo com; adversário de, dat. ou gen. ♦ τὸ διάφορον 6 diferença; divergência 7 contestação 8 saldo; quantia. 〈διαφέρω〉</p></section></article>\n<article id=\"entry-dgp-9875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφορότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1357 na letra δ · nº geral 9875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diferença. 〈διάφορος〉</p></section></article>\n<article id=\"entry-dgp-9876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφόρως</h1><div class=\"entry-meta\"><span>DGP · ordem 1358 na letra δ · nº geral 9876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 diferentemente; de modo diferente de, gen. 2 em oposição a, dat.: δ. ἔχειν plat. estar em oposição, ser hostil 3 de modo superior; com distinção.</p></section></article>\n<article id=\"entry-dgp-9877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφραγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1359 na letra δ · nº geral 9877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barreira; fecho; separação 2 Anat. diafragma 3 véu palatino 4 cartilagem de separação nasal. 〈διαφράσσω〉</p></section></article>\n<article id=\"entry-dgp-9878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφράγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1360 na letra δ · nº geral 9878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar com paliçadas; entrincheirar; cercar ♦ méd. 2 fazer barricadas para si.</p></section></article>\n<article id=\"entry-dgp-9879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1361 na letra δ · nº geral 9879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. διεπέφραδε) dizer claramente; dizer; explicar.</p></section></article>\n<article id=\"entry-dgp-9880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1362 na letra δ · nº geral 9880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω tapar; dividir com tapumes; fazer barricadas; interceptar.</p></section></article>\n<article id=\"entry-dgp-9881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1363 na letra δ · nº geral 9881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deixar passar.</p></section></article>\n<article id=\"entry-dgp-9882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφροντίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1364 na letra δ · nº geral 9882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 meditar 2 meditar sobre; pensar em; con­siderar; estudar, ac.</p></section></article>\n<article id=\"entry-dgp-9883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυγγάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1365 na letra δ · nº geral 9883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = διαφεύγω.</p></section></article>\n<article id=\"entry-dgp-9884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1366 na letra δ · nº geral 9884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio de escapar, de fugir de, gen. ou ἐκ e gen. 〈διαφεύγω〉</p></section></article>\n<article id=\"entry-dgp-9885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1367 na letra δ · nº geral 9885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separação 2 Anat. diáfise 3 intervalo; espaço oco; fenda 4 veio de uma pedra 5 filão (mineral). 〈διαφύω〉</p></section></article>\n<article id=\"entry-dgp-9886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυλακτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1368 na letra δ · nº geral 9886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διαφυλάσσω.</p></section></article>\n<article id=\"entry-dgp-9887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυλακτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1369 na letra δ · nº geral 9887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para conservar, para proteger, gen. 〈διαφυλάσσω〉</p></section></article>\n<article id=\"entry-dgp-9888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυλάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1370 na letra δ · nº geral 9888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. διαφυλάξω, aor. διεφύλαξα etc.) 1 guardar com cuidado; velar com cuidado; vigiar estreitamente 2 observar (as medidas prescritas) 3 observar; estar atento a, or. conj. (ὅτι); δ. τὸ μή e inf. 4 recordar; guardar na memória ♦ méd. 5 vigiar para si mesmo.</p></section></article>\n<article id=\"entry-dgp-9889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφυσάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1371 na letra δ · nº geral 9889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encher de ar 2 dispersar com um sopro; dissipar 3 soprar através.</p></section></article>\n<article id=\"entry-dgp-9890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1372 na letra δ · nº geral 9890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. διήφυσε) 1 extrair; retirar; arrancar ♦ méd. 2 extrair-se sem cessar. 〈διά, ἀφύσσω〉</p></section></article>\n<article id=\"entry-dgp-9891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1373 na letra δ · nº geral 9891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.2 διέφυν, perf. διαπέφυκα e pres. méd. διαφύομαι) 1 brotar separado; separar-se; dissociar-se 2 brotar entre, no meio de, gen.; brotar como parasita; crescer (numa fenda) 3 germinar 4 perf. estar enraizado em, gen. 5 unir-se a, apegar-se a; ter estreitas relações com, algo, gen. 6 (tempo) escoar-se no intervalo; transcorrer.</p></section></article>\n<article id=\"entry-dgp-9892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφῶ, ῇς</h1><div class=\"entry-meta\"><span>DGP · ordem 1374 na letra δ · nº geral 9892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de διαφίημι.</p></section></article>\n<article id=\"entry-dgp-9893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφωνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1375 na letra δ · nº geral 9893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφωνήσω) 1 estar em desacordo; estar em dissonância; não concordar com algo ou alguém, dat. ou πρός e ac. 2 não corresponder ao esperado ou prometido; falhar; faltar a, gen.: διαφωνεῖ τι τῶν χρημάτων pol. algum dos bens não está de acordo 3 cometer um erro; falhar 4 tard. perecer.</p></section></article>\n<article id=\"entry-dgp-9894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1376 na letra δ · nº geral 9894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dissonante; divergente; em desacordo com, dat. 〈διά, φωνή〉</p></section></article>\n<article id=\"entry-dgp-9895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1377 na letra δ · nº geral 9895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διαφαύσκω.</p></section></article>\n<article id=\"entry-dgp-9896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαφωτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1378 na letra δ · nº geral 9896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαφωτίσω, át. διαφωτιῶ) 1 clarear; iluminar 2 intr. brilhar.</p></section></article>\n<article id=\"entry-dgp-9897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαχάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1379 na letra δ · nº geral 9897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. afastar-se.</p></section></article>\n<article id=\"entry-dgp-9898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαχαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1380 na letra δ · nº geral 9898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέχανον, perf. διακέχηνα) entreabrir-se.</p></section></article>\n<article id=\"entry-dgp-9899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαχαλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1381 na letra δ · nº geral 9899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abrir 2 distender; relaxar; abrandar 3 intr. abrir-se; separar-se.</p></section></article>\n<article id=\"entry-dgp-9900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαχαράσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1382 na letra δ · nº geral 9900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar por um traço; separar 2 gravar; traçar gravando 3 escrever 4 arranhar; esfregar (olho) ♦ méd. 5 raspar; arranhar.</p></section></article>\n";
